<?php
/** TEMP PS S1688 mq — CALC v1.0 pagal Raimio maketą: DATA img_suo.txt/img_maisas-dubenelis.txt → WP media (URL įrašomi į opciją ps_relaunch_img); naujas laukas PS_HERO_EUR2N („1,10 €" be „nuo"); f=siusti — terra calc laukai + kampanija; f=html — užpildytas HTML; f=nars — 390 px nuotrauka. */
add_action('init', function(){
  if (!isset($_GET['ps_s1688mq'])) return; global $wpdb; $o=array('v'=>'S1688 mq'); $f=$_GET['ps_s1688mq']; $t=Petshop_Relaunch::t();
  $img=get_option('ps_relaunch_img',array());
  foreach(array('suo'=>'d_img_suo_txt','maisas'=>'d_img_maisas_dubenelis_txt') as $k=>$g){ if(!empty($_GET[$g])){ $id=(int)$_GET[$g]; $p=get_attached_file($id); if($p){ $raw=base64_decode(file_get_contents($p)); $up=wp_upload_dir(); wp_mkdir_p($up['basedir'].'/ps-relaunch'); file_put_contents($up['basedir'].'/ps-relaunch/'.$k.'.jpg',$raw); $img[$k]=$up['baseurl'].'/ps-relaunch/'.$k.'.jpg'; wp_delete_attachment($id,true); } } }
  if($img) update_option('ps_relaunch_img',$img,false); $o['img']=$img;
  $tok=Petshop_Sender_Adapter::get_stored_token('marketing');
  $api=function($m,$p,$b=null) use($tok){ $a=array('method'=>$m,'timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.$tok,'Accept'=>'application/json','Content-Type'=>'application/json')); if($b!==null) $a['body']=wp_json_encode($b); $r=wp_remote_request('https://api.sender.net/v2'.$p,$a); if(is_wp_error($r)) return array('code'=>0); return array('code'=>wp_remote_retrieve_response_code($r),'body'=>json_decode(wp_remote_retrieve_body($r),true)); };
  $pg=function($slug){ $p=get_page_by_path($slug); return $p?get_permalink($p):home_url('/'); };
  $html=str_replace(array('__SUO__','__MAISAS__','__KONTAKTAI__','__PRISTATYMAS__','__GRAZINIMAS__'),array($img['suo']??'',$img['maisas']??'',$pg('kontaktai'),$pg('pristatymas'),$pg('grazinimas')),base64_decode(''));
  $o['puslapiai']=array($pg('kontaktai'),$pg('pristatymas'),$pg('grazinimas'));
  $laukai=function() use($wpdb,$t){ $row=$wpdb->get_row("SELECT * FROM $t WHERE email='terra@gyvunai.lt'",ARRAY_A); $d=json_decode($row['duomenys'],true); $pr=wc_get_product(12466); $up=wp_upload_dir(); $pak='Pakuotės'; if(preg_match('/(\d+(?:[,.]\d+)?)\s?kg/iu',$pr->get_name(),$m)) $pak=str_replace('.',',',$m[1]).' kg maišo';
    $fl=array('PS_HERO_SEG'=>'calc','PS_HERO_PAV'=>$d['pav'],'PS_HERO_KAINA'=>number_format((float)$d['kaina'],2,',','').' €','PS_HERO_IMG'=>$up['baseurl'].'/ps-relaunch/12466.jpg','PS_HERO_URL'=>$d['url'],'PS_HERO_GYV'=>'šuniui','PS_HERO_ANTR'=>'','PS_HERO_KODEL'=>'nes prenumeruojate Petshop.lt naujienas','PS_HERO_PAK'=>$pak);
    foreach($d['eilutes'] as $i=>$e){ $n=$i+1; $fl["PS_HERO_KG$n"]=$e['kg'].' kg'; $fl["PS_HERO_EUR$n"]='nuo '.$e['eur_nuo'].' €'; $fl["PS_HERO_INFO$n"]=$e['g'].' g/d · maišo užtenka '.$e['d'].' d.'; $fl["PS_HERO_U$n"]=$e['url']; $fl["PS_HERO_D$n"]=$e['d']; if($n===2){ $fl['PS_HERO_G2']=$e['g'].' g'; $fl['PS_HERO_EUR2N']=$e['eur_nuo'].' €'; } } return $fl; };
  if($f==='siusti'){ $r=$api('GET','/fields?limit=100'); $yra=array(); foreach((array)($r['body']['data']??array()) as $x) $yra[$x['title']]=1; foreach(array('PS_HERO_EUR2N','PS_HERO_D1','PS_HERO_D3') as $l) $o[$l]=isset($yra[$l])?'buvo':$api('POST','/fields',array('title'=>$l,'type'=>'text'))['code'];
    $fl=$laukai(); $o['patch']=$api('PATCH','/subscribers/terra%40gyvunai.lt',array('fields'=>$fl))['code'];
    $b=array('title'=>'TEST relaunch CALC v1.0 '.date('H:i'),'subject'=>'Kiek kainuoja jūsų augintinio maistas per dieną?','from'=>'Petshop.lt','reply_to'=>'terra@petshop.lt','content_type'=>'html','content'=>$html,'groups'=>array('bDxp2q'),'preheader'=>'{{ps_hero_eur2}} per dieną {{ps_hero_kg2}} {{ps_hero_gyv}}. Skaičiavome pagal maistą, kurį anksčiau pirkote pas mus.');
    $r=$api('POST','/campaigns',$b); $id=$r['body']['data']['id']??''; $o['kamp']=array('kurti'=>$r['code'],'id'=>$id,'err'=>$r['body']['errors']??null); if($id){ $o['send']=$api('POST','/campaigns/'.$id.'/send')['code']; } $o['html_kb']=round(strlen($html)/1024,1); }
  elseif($f==='html'){ $fl=$laukai(); $s=$html; foreach($fl as $k=>$v) $s=str_replace('{{'.strtolower($k).'}}',$v,$s); $s=str_replace('{{unsubscribe_link}}','#',$s); header('Content-Type: text/html; charset=utf-8'); echo $s; exit; }
  elseif($f==='nars'){ $o['shots']=array(array('n'=>'s1688_v10_390','u'=>home_url('/?ps_s1688mq=html'),'w'=>390,'h'=>900,'full'=>1),array('n'=>'s1688_v10_640','u'=>home_url('/?ps_s1688mq=html'),'w'=>640,'h'=>900,'full'=>1)); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
